from collections import Counter, deque

def transform(grid):
    a = [list(row) for row in grid]
    h, w = len(a), len(a[0])
    bg = a[0][0]
    rings = {}

    for color in {v for row in a for v in row if v != bg}:
        seen = set()
        for r in range(h):
            for c in range(w):
                if a[r][c] != color or (r, c) in seen:
                    continue

                q = deque([(r, c)])
                seen.add((r, c))
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w
                                and a[ny][nx] == color
                                and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))

                r0 = min(y for y, x in cells)
                r1 = max(y for y, x in cells)
                c0 = min(x for y, x in cells)
                c1 = max(x for y, x in cells)
                hh, ww = r1 - r0 + 1, c1 - c0 + 1
                if hh < 3 or ww < 3:
                    continue

                perimeter = 2 * hh + 2 * ww - 4
                if len(cells) != perimeter:
                    continue
                if (any(a[r0][x] != color or a[r1][x] != color
                        for x in range(c0, c1 + 1))
                        or any(a[y][c0] != color or a[y][c1] != color
                               for y in range(r0, r1 + 1))):
                    continue
                rings.setdefault(color, []).append((r0, r1, c0, c1))

    if not rings:
        return a

    frame = max(
        rings,
        key=lambda color: (
            len(rings[color]),
            sum((r1 - r0 + 1) * (c1 - c0 + 1)
                for r0, r1, c0, c1 in rings[color]),
            -color
        )
    )

    for r0, r1, c0, c1 in rings[frame]:
        region = [row[c0 + 1:c1] for row in a[r0 + 1:r1]]
        rh, rw = len(region), len(region[0])
        best_key = None
        best_pattern = None
        best_period = None

        for ph in range(1, rh + 1):
            for pw in range(1, rw + 1):
                counts = [[Counter() for _ in range(pw)] for _ in range(ph)]
                for i in range(rh):
                    for j in range(rw):
                        counts[i % ph][j % pw][region[i][j]] += 1

                pattern = []
                for i in range(ph):
                    prow = []
                    for j in range(pw):
                        counter = counts[i][j]
                        most = max(counter.values())
                        tied = [v for v, n in counter.items() if n == most]
                        prow.append(bg if bg in tied else min(tied))
                    pattern.append(prow)

                errors = sum(
                    region[i][j] != pattern[i % ph][j % pw]
                    for i in range(rh) for j in range(rw)
                )
                key = (ph * pw + 2 * errors, ph * pw, ph + pw, ph, pw)
                if best_key is None or key < best_key:
                    best_key = key
                    best_pattern = pattern
                    best_period = (ph, pw)

        ph, pw = best_period
        for i in range(rh):
            for j in range(rw):
                a[r0 + 1 + i][c0 + 1 + j] = best_pattern[i % ph][j % pw]

    return a
